//   (component
//     (import "host" (instance $h
//       (export "sleep" (func async (param "how-long" u64)))))
//     (core module $Memory (memory (export "mem") 1))
//     (core instance $memory (instantiate $Memory))
//     (alias core export $memory "mem" (core memory $mem))
//     (core module $M
//       (import "" "mem" (memory 1))
//       (import "" "sleep" (func $sleep (param i64)))
//       (import "" "sleep-async" (func $sleep-async (param i64) (result i32)))
//       (import "" "task.return" (func $task.return))
//       (import "" "task.return-u32" (func $task.return-u32 (param i32)))
//       (import "" "subtask.cancel" (func $subtask.cancel
//         (param i32) (result i32)))
//       (import "" "subtask.drop" (func $subtask.drop (param i32)))
//       (import "" "waitable.join" (func $waitable.join (param i32 i32)))
//       (import "" "waitable-set.new" (func $waitable-set.new (result i32)))
//       (import "" "waitable-set.wait" (func $waitable-set.wait
//         (param i32 i32) (result i32)))
//       (import "" "waitable-set.drop" (func $waitable-set.drop (param i32)))
//
//       ;; async export calling the sync-lowered sleep
//       (func (export "run-sync-lower") (param i64)
//         (call $sleep (local.get 0))
//         (call $task.return))
//
//       ;; sync export calling the sync-lowered sleep
//       (func (export "run-sync-export") (param i64)
//         (call $sleep (local.get 0)))
//
//       ;; async export calling the async-lowered sleep, then waiting for the
//       ;; subtask event: returns lower-status | state << 4 | event-code << 8
