TEST(ComponentHostFunction, SyncCallThroughComponent) {
  // The provider outlives the VM whose instances import from it.
  auto Host = newHostInstance();
  VM::ComponentVM VM(componentConf());
  loadWithHost(VM, *Host, HostSyncWasm);

  std::vector<ComponentValVariant> Params{ComponentValVariant{uint32_t(5)}};
  std::vector<ComponentValType> Types{ComponentValType(ComponentTypeCode::U32)};
  auto Added = VM.execute("run-add", Params, Types);
  ASSERT_TRUE(Added);
  ASSERT_EQ(Added->size(), 1u);
  EXPECT_EQ(std::get<uint32_t>((*Added)[0].first), 105u);

  Params[0] = ComponentValVariant{uint32_t(3)};
  auto Repeated = VM.execute("run-repeat", Params, Types);
  ASSERT_TRUE(Repeated);
  ASSERT_EQ(Repeated->size(), 1u);
  EXPECT_EQ(std::get<uint32_t>((*Repeated)[0].first), 97006u);
}

// A guest that stores its strings as UTF-16 calls `repeat` with one:
//   (component
//     (import "host" (instance $h
//       (export "repeat" (func (param "count" u32) (param "text" string)
//         (result (list u8))))))
//     (core module $Memory
//       (memory (export "mem") 1)
//       ;; "h\u{e9}" as UTF-16.
//       (data (i32.const 8) "h\00\e9\00")
//       (func (export "realloc") (param i32 i32 i32 i32) (result i32)
//         (i32.const 1024)))
//     (core instance $memory (instantiate $Memory))
//     (canon lower (func $h "repeat") string-encoding=utf16
//       (memory (core memory $memory "mem"))
//       (realloc (core func $memory "realloc")) (core func $repeat))
//     (core module $M
//       (import "" "mem" (memory 1))
//       (import "" "repeat" (func $repeat (param i32 i32 i32 i32)))
//       ;; What the host made of the two code units: the byte count in the
//       ;; top byte, then the first three bytes.
//       (func (export "run") (result i32)
//         (call $repeat
//           (i32.const 1) (i32.const 8) (i32.const 2) (i32.const 64))
//         (i32.or (i32.shl (i32.load (i32.const 68)) (i32.const 24))
//           (i32.and (i32.load (i32.load (i32.const 64)))
//             (i32.const 0xffffff)))))
//     (core instance $m (instantiate $M (with "" (instance
//       (export "mem" (memory $memory "mem"))
//       (export "repeat" (func $repeat))))))
//     (func (export "run") (result u32) (canon lift (core func $m "run"))))
