//     (import "host" (instance $h
//       (export "counter" (type $ct (sub resource)))
//       (export "make-counter" (func (param "start" u32) (result (own $ct))))
//       (export "counter-bump" (func (param "c" (borrow $ct)) (result u32)))))
//     (alias export $h "counter" (type $counter))
