// produce() -> stream<u32>: parks one host value for the guest to read.
class ProduceValue : public Runtime::Component::HostFunction<ProduceValue> {
public:
  explicit ProduceValue(ComponentValVariant V) noexcept : Val(std::move(V)) {}
  Expect<Runtime::Component::Stream<uint32_t>>
  body(Runtime::Component::CallingFrame &Frame) {
    const auto Ends = Frame.getExecutor().newHostStream(
        Frame, false, ComponentValType(ComponentTypeCode::U32));
    Runtime::Component::Stream<uint32_t> Out{Ends.second};
    Frame.getExecutor().spawnStreamWrite(Frame, Ends.first, Val);
    return Out;
  }

private:
  ComponentValVariant Val;
};

//   (component
//     (import "host" (instance $h
//       (export "produce" (func (result (stream u32))))))
//     (type $st (stream u32))
//     (core module $Memory (memory (export "mem") 1))
//     (core instance $memory (instantiate $Memory))
//     (alias core export $memory "mem" (core memory $mem))
//     (core module $M
//       (import "" "mem" (memory 1))
//       (import "" "produce" (func $produce (result i32)))
//       (import "" "stream.read" (func $read (param i32 i32 i32) (result i32)))
//       (import "" "stream.drop-readable" (func $drop-r (param i32)))
//       (import "" "task.return" (func $task.return (param i32)))
//       ;; Read the one value the host parked, then return it.
//       (func (export "run")
//         (local $s i32)
//         (local.set $s (call $produce))
//         (drop (call $read (local.get $s) (i32.const 1024) (i32.const 1)))
//         (call $drop-r (local.get $s))
//         (call $task.return (i32.load (i32.const 1024)))))
//     (canon lower (func $h "produce") (core func $produce))
//     (canon stream.read $st (memory $mem) (core func $read))
//     (canon stream.drop-readable $st (core func $drop-r))
//     (canon task.return (result u32) (core func $task.return))
//     (core instance $m (instantiate $M (with "" (instance
//       (export "mem" (memory $mem))
//       (export "produce" (func $produce))
//       (export "stream.read" (func $read))
//       (export "stream.drop-readable" (func $drop-r))
//       (export "task.return" (func $task.return))))))
//     (func (export "run") async (result u32)
//       (canon lift (core func $m "run") async)))
