//       (func $set-wake (param $v i32)
//         (global.set $g (local.get $v))
//         (call $resume-later (global.get $main)))
//       (elem (i32.const 0) func $set $set-wake)
//       ;; A promote to a ready thread hands over the stack; one to a thread
//       that
//       ;; is not ready parks instead, and another ready thread runs. The
//       result
//       ;; records which thread ran at each step.
//       (func (export "run")
//         (local $t1 i32) (local $t2 i32) (local $acc i32)
//         (global.set $main (call $index))
//         (local.set $t1 (call $new (i32.const 0) (i32.const 1)))
//         (call $resume-later (local.get $t1))
//         (drop (call $yield-then-promote (local.get $t1)))
//         (local.set $acc (global.get $g))
//         (local.set $t2 (call $new (i32.const 1) (i32.const 2)))
//         (call $resume-later (call $new (i32.const 1) (i32.const 3)))
//         (drop (call $suspend-then-promote (local.get $t2)))
//         (local.set $acc (i32.add (i32.mul (local.get $acc) (i32.const 10))
//           (global.get $g)))
//         (drop (call $suspend-then-resume (local.get $t2)))
//         (local.set $acc (i32.add (i32.mul (local.get $acc) (i32.const 10))
//           (global.get $g)))
//         (call $task.return (local.get $acc))))
//     (core func $new (canon thread.new-indirect $start (table $tab)))
//     (canon thread.index (core func $index))
//     (canon thread.resume-later (core func $resume-later))
//     (canon thread.suspend-then-resume (core func $suspend-then-resume))
//     (canon thread.suspend-then-promote (core func $suspend-then-promote))
//     (canon thread.yield-then-promote (core func $yield-then-promote))
//     (canon task.return (result u32) (core func $task.return))
//     (core instance $m (instantiate $M (with "" (instance
//       (export "tab" (table $tab))
//       (export "thread.new-indirect" (func $new))
//       (export "thread.index" (func $index))
//       (export "thread.resume-later" (func $resume-later))
//       (export "thread.suspend-then-resume" (func $suspend-then-resume))
//       (export "thread.suspend-then-promote" (func $suspend-then-promote))
//       (export "thread.yield-then-promote" (func $yield-then-promote))
//       (export "task.return" (func $task.return))))))
//     (func (export "run") async (result u32)
//       (canon lift (core func $m "run") async)))
