  //         (i32.wrap_i64 (i64.shr_u (local.get $pair) (i64.const 32))))
  //       (i32.store (i32.const 0) (i32.wrap_i64 (local.get $pair)))
  //       (i32.store (i32.const 4) (i32.const -16))
  //       (i32.store (i32.const 8) (i32.const 32))
  //       (i32.const 0)))
  //   (canon lower (func $h "produce") (core func $produce))
  //   (canon stream.new $st (core func $new))
