  //   (canon waitable-set.new (core func $set.new))
  //   (canon task.return (result $S) (core func $return))
  //   (core module $M
  //     (import "" "new" (func $new (result i64)))
  //     (import "" "drop-readable" (func $drop-readable (param i32)))
  //     (import "" "set.new" (func $set.new (result i32)))
  //     (import "" "return" (func $return (param i32)))
  //     ;; The readable end left with the result: the next handle takes its
  //     ;; slot.
  //     (func (export "give") (local $rx i32)
  //       (local.set $rx (i32.wrap_i64 (call $new)))
  //       (call $return (local.get $rx))
  //       (if (i32.ne (call $set.new) (local.get $rx)) (then unreachable)))
  //     (func (export "give-and-drop") (local $rx i32)
